import chess

MOTIF_NAME = 'material edge with activity tiebreak'
MOTIF_DESCRIPTION = 'The side to move has more total piece value than the opponent, or with equal material attacks more enemy pieces than the opponent attacks.'

PIECE_VALUES = {
    chess.PAWN: 100,
    chess.KNIGHT: 300,
    chess.BISHOP: 300,
    chess.ROOK: 500,
    chess.QUEEN: 900,
    chess.KING: 0,
}

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    material = 0
    for piece_type, value in PIECE_VALUES.items():
        material += value * (len(board.pieces(piece_type, stm)) - len(board.pieces(piece_type, opp)))
    if material != 0:
        return material > 0
    our_hits = 0
    their_hits = 0
    for sq in chess.SQUARES:
        piece = board.piece_at(sq)
        if piece is None:
            continue
        hits = 0
        for target in board.attacks(sq):
            victim = board.piece_at(target)
            if victim is not None and victim.color != piece.color:
                hits += 1
        if piece.color == stm:
            our_hits += hits
        else:
            their_hits += hits
    return our_hits > their_hits

MOTIF_NAME = 'development lead on even terms'
MOTIF_DESCRIPTION = 'With material roughly equal, the side to move has a clear development lead: at least two more units of development (minor pieces off their back rank plus a king tucked off the central file) than the opponent.'

VAL = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}


def _mat(board, color):
    s = 0
    for pt, v in VAL.items():
        s += v * len(board.pieces(pt, color))
    return s


def _dev(board, color):
    back = 0 if color == chess.WHITE else 7
    n = 0
    for pt in (chess.KNIGHT, chess.BISHOP):
        for sq in board.pieces(pt, color):
            if chess.square_rank(sq) != back:
                n += 1
    ksq = board.king(color)
    if ksq is not None and chess.square_rank(ksq) == back and chess.square_file(ksq) != 4:
        n += 1
    return n


def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if abs(_mat(board, stm) - _mat(board, opp)) > 1:
        return False
    return _dev(board, stm) - _dev(board, opp) >= 2

import chess

MOTIF_NAME = 'enemy-half pawn space edge'
MOTIF_DESCRIPTION = "The side to move's pawns attack at least three more distinct squares on the opponent's half of the board than the opponent's pawns attack on the side-to-move's half, reflecting a clear space advantage."

def _space(board, color):
    half = 0xFFFFFFFF00000000 if color == chess.WHITE else 0x00000000FFFFFFFF
    mask = 0
    for sq in board.pieces(chess.PAWN, color):
        mask |= int(board.attacks(sq))
    return bin(mask & half).count('1')

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    return _space(board, stm) - _space(board, not stm) >= 3

import chess

MOTIF_NAME = 'accumulated positional pluses score'
MOTIF_DESCRIPTION = 'The side to move has at least three points of positional advantages such as the bishop pair, pinned enemy pieces, advanced passed pawns, rooks on open files, and the safer king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    score = 0
    sb = len(board.pieces(chess.BISHOP, stm))
    ob = len(board.pieces(chess.BISHOP, opp))
    if sb >= 2 and ob < 2:
        score += 2
    elif ob >= 2 and sb < 2:
        score -= 2
    pi = 0
    ps = 0
    for sq, piece in board.piece_map().items():
        if piece.piece_type in (chess.PAWN, chess.KING):
            continue
        if board.is_pinned(piece.color, sq):
            if piece.color == opp:
                pi += 1
            else:
                ps += 1
    score += min(pi, 2) - min(ps, 2)
    pawns = {stm: list(board.pieces(chess.PAWN, stm)), opp: list(board.pieces(chess.PAWN, opp))}
    fc = {stm: [0] * 8, opp: [0] * 8}
    for c in (stm, opp):
        for sq in pawns[c]:
            fc[c][chess.square_file(sq)] += 1
    def passed(c, sq):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for e in pawns[not c]:
            if abs(chess.square_file(e) - f) <= 1:
                er = chess.square_rank(e)
                if (c == chess.WHITE and er > r) or (c == chess.BLACK and er < r):
                    return False
        return True
    def prog(c, sq):
        r = chess.square_rank(sq)
        return r - 1 if c == chess.WHITE else 6 - r
    pp = {c: sum(prog(c, s) for s in pawns[c] if passed(c, s) and prog(c, s) >= 2) for c in (stm, opp)}
    d = pp[stm] - pp[opp]
    if d >= 4:
        score += 2
    elif d >= 2:
        score += 1
    elif d <= -4:
        score -= 2
    elif d <= -2:
        score -= 1
    dbl = fc[opp].count(0)
    dbl_s = sum(1 for f in range(8) if fc[stm][f] >= 2)
    dbl_o = sum(1 for f in range(8) if fc[opp][f] >= 2)
    score += max(-2, min(2, dbl_o - dbl_s))
    rd = 0
    for c, sign in ((stm, 1), (opp, -1)):
        for s in board.pieces(chess.ROOK, c):
            f = chess.square_file(s)
            if fc[stm][f] == 0 and fc[opp][f] == 0:
                rd += sign
            elif fc[c][f] == 0:
                rd += sign
    score += max(-2, min(2, rd))
    queens = len(board.pieces(chess.QUEEN, chess.WHITE)) + len(board.pieces(chess.QUEEN, chess.BLACK))
    ks = board.king(stm)
    ko = board.king(opp)
    if queens and ks is not None and ko is not None:
        kfc = 3 <= chess.square_file(ks) <= 4
        kfo = 3 <= chess.square_file(ko) <= 4
        if kfo and not kfc:
            score += 2
        elif kfc and not kfo:
            score -= 2
    return score >= 3

import chess

MOTIF_NAME = 'activity compensation without material edge'
MOTIF_DESCRIPTION = 'With equal or less material, the side to move controls many more squares than the opponent, showing superior piece activity.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    val = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
           chess.ROOK: 5, chess.QUEEN: 9}
    mat = sum(v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
              for pt, v in val.items())
    if mat > 0:
        return False
    ours = set()
    theirs = set()
    for sq, piece in board.piece_map().items():
        if piece.color == stm:
            ours.update(board.attacks(sq))
        else:
            theirs.update(board.attacks(sq))
    return len(ours) - len(theirs) >= 8

import chess

MOTIF_NAME = 'king ring siege edge'
MOTIF_DESCRIPTION = 'The side to move has at least three pieces attacking squares adjacent to the enemy king, at least two more than the opponent has around the side-to-move king.'

def _ring_count(board, color):
    ksq = board.king(not color)
    if ksq is None:
        return 0
    f0 = chess.square_file(ksq)
    r0 = chess.square_rank(ksq)
    pieces = set()
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = f0 + df
            nr = r0 + dr
            if 0 <= nf < 8 and 0 <= nr < 8:
                for a in board.attackers(color, chess.square(nf, nr)):
                    pieces.add(a)
    return len(pieces)

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    mine = _ring_count(board, stm)
    if mine < 3:
        return False
    return mine - _ring_count(board, not stm) >= 2

MOTIF_NAME = 'tactical pressure on loose enemy pieces'
MOTIF_DESCRIPTION = 'With material nearly even, the side to move creates more tactical pressure, in the form of enemy non-pawn pieces that are en prise, underdefended, or attacked by pawns, than it suffers on its own pieces.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    val = (0, 1, 3, 3, 5, 9, 0)
    ms = mo = 0
    for p in board.piece_map().values():
        if p.color == stm:
            ms += val[p.piece_type]
        else:
            mo += val[p.piece_type]
    d = ms - mo
    if d > 1 or d < -2:
        return False
    net = 0
    for sq, p in board.piece_map().items():
        pt = p.piece_type
        if pt == chess.PAWN or pt == chess.KING:
            continue
        sa = board.attackers(stm, sq)
        oa = board.attackers(opp, sq)
        nsa = len(sa)
        noa = len(oa)
        if p.color == opp:
            if nsa:
                if not noa:
                    net += 2
                elif nsa > noa:
                    net += 1
                for a in sa:
                    if board.piece_type_at(a) == chess.PAWN:
                        net += 1
                        break
        else:
            if noa:
                if not nsa:
                    net -= 2
                elif noa > nsa:
                    net -= 1
                for a in oa:
                    if board.piece_type_at(a) == chess.PAWN:
                        net -= 1
                        break
    return net >= 2
